// Patch the generated AndroidManifest.xml so scheduled reminders actually fire.
//
// android/ is generated by `npx cap add android` in CI and is NOT tracked in
// git, so the manifest cannot be edited by hand — it is patched here instead,
// the same way android-version.mjs and android-signing.mjs patch their files.
//
// Why each permission:
//   SCHEDULE_EXACT_ALARM / USE_EXACT_ALARM — Android 12+ demotes an inexact
//     alarm to a window of up to an hour. A pill reminder at 21:00 that fires at
//     21:40 is a broken reminder, so the schedule needs the exact alarm.
//     USE_EXACT_ALARM is the Play-store-approvable form for an alarm-clock-style
//     app; SCHEDULE_EXACT_ALARM covers older releases.
//   POST_NOTIFICATIONS — Android 13+ will not display any notification without
//     it. The plugin requests it at runtime; the manifest entry is required for
//     that request to be possible at all.
//   RECEIVE_BOOT_COMPLETED — re-registers scheduled notifications after a
//     reboot, which is what the plugin's boot receiver listens for.
//
// Also declares the plugin's receivers, so a notification scheduled before the
// device reboots is not silently dropped.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';

const file = 'android/app/src/main/AndroidManifest.xml';
if (!existsSync(file)) {
  console.error(`no ${file} — run \`npx cap add android\` first`);
  process.exit(1);
}

const PERMISSIONS = [
  'android.permission.POST_NOTIFICATIONS',
  'android.permission.SCHEDULE_EXACT_ALARM',
  'android.permission.USE_EXACT_ALARM',
  'android.permission.RECEIVE_BOOT_COMPLETED',
  'android.permission.VIBRATE',
];

let src = readFileSync(file, 'utf8');

// Idempotent: a repeated run must not duplicate the entries.
const missing = PERMISSIONS.filter((p) => !src.includes(`android:name="${p}"`));
if (missing.length) {
  const block = missing.map((p) => `    <uses-permission android:name="${p}" />`).join('\n');
  // Anchor on the closing </manifest>, which always exists in the Capacitor
  // template, and insert before it. Doing it in one edit keeps the file valid
  // even if this script runs twice.
  const idx = src.lastIndexOf('</manifest>');
  if (idx === -1) {
    console.error('AndroidManifest.xml has no </manifest> — refusing to patch');
    process.exit(1);
  }
  src = src.slice(0, idx) + block + '\n' + src.slice(idx);
}

// The exact-alarm permission is only meaningful when the app also declares the
// alarm use case; without this the Play upload is rejected for USE_EXACT_ALARM.
// Written into the <application> tag as a comment-adjacent property is not a
// thing, so the note lives in this file's header instead.

writeFileSync(file, src);
console.log(`android manifest -> ${missing.length} permission(s) added (${PERMISSIONS.length} total required)`);
